/* The vendor app's FPGA start-up sequence, generated by tools/gen_vendor_init.py. */
#ifndef FPGA_VENDOR_INIT_H
#define FPGA_VENDOR_INIT_H
#include <stdint.h>

typedef struct {
	uint8_t addr;
	uint16_t val;
	uint32_t wait_us;      /* the vendor's pause BEFORE this write (0 = none); part of the protocol */
} fpga_init_write_t;

extern const fpga_init_write_t FPGA_VENDOR_INIT[];
extern const int FPGA_VENDOR_INIT_N;

#endif
